<?php require __DIR__.'/app/layout.php';must_login();
$q=trim((string)($_GET['q']??''));$cap=(int)($_GET['capacity']??0);$equipment=trim((string)($_GET['equipment']??''));$status=(string)($_GET['status']??'active');
$sql='SELECT * FROM rooms WHERE status<>\'archived\'';$params=[];
if($status==='maintenance'||$status==='active'){$sql.=' AND status=?';$params[]=$status;}
if($q!==''){$sql.=' AND (name LIKE ? OR location LIKE ? OR description LIKE ?)';array_push($params,"%$q%","%$q%","%$q%");}
if($cap>0){$sql.=' AND capacity>=?';$params[]=$cap;}
if($equipment!==''){$sql.=' AND equipment LIKE ?';$params[]="%$equipment%";}
$sql.=' ORDER BY status,name';$rooms=all_rows($sql,$params);
page_start('Salles de réunion','rooms'); titlebar('Espaces disponibles','Salles de réunion','Découvrez les salles et leurs équipements, puis réservez le créneau souhaité.'); ?>
<form class="filterbar" method="get"><input class="form-control flex-grow-1" name="q" placeholder="Rechercher une salle…" value="<?=h($q)?>"><input type="number" class="form-control" name="capacity" min="1" value="<?= $cap>0?h($cap):'' ?>" placeholder="Capacité min."><input name="equipment" class="form-control" placeholder="Équipement" value="<?=h($equipment)?>"><select name="status" class="form-select"><option value="active" <?=$status==='active'?'selected':''?>>Disponibles</option><option value="maintenance" <?=$status==='maintenance'?'selected':''?>>Maintenance</option><option value="all" <?=$status==='all'?'selected':''?>>Toutes</option></select><button class="btn btn-primary"><i class="bi bi-search"></i> Filtrer</button><a href="<?=h(url('reservation.php'))?>" class="btn btn-outline-primary">Réserver</a></form>
<div class="row g-4"><?php foreach($rooms as $r):?><div class="col-sm-6 col-xl-4"><div class="panel p-0 room-card h-100"><img loading="lazy" class="room-cover" src="<?=h(room_image($r['image']))?>" alt="Salle <?=h($r['name'])?>"><div class="room-body"><div class="d-flex justify-content-between align-items-start gap-2"><h3><?=h($r['name'])?></h3><?=pill($r['status'])?></div><p class="muted mb-3"><?=h(textclip((string)$r['description'],100))?></p><div class="room-meta mb-3"><span><i class="bi bi-people"></i> <?= $r['capacity']===null?'Capacité à préciser':h($r['capacity']).' places' ?></span><span><i class="bi bi-geo-alt"></i> <?=h($r['location']?:'Non précisé')?></span></div><div class="small muted mb-3"><i class="bi bi-projector me-1"></i><?=h(textclip((string)($r['equipment']?:'Équipements non renseignés'),90))?></div><div class="d-flex gap-2"><a class="btn btn-outline-primary btn-sm flex-grow-1" href="<?=h(url('salle.php?id='.$r['id']))?>">Détails</a><?php if($r['status']==='active'):?><a class="btn btn-primary btn-sm flex-grow-1" href="<?=h(url('reservation.php?room_id='.$r['id']))?>">Réserver</a><?php endif;?></div></div></div></div><?php endforeach;?>
<?php if(!$rooms):?><div class="col-12"><div class="panel empty-state"><i class="bi bi-door-closed"></i>Aucune salle ne correspond aux filtres.</div></div><?php endif;?></div>
<?php page_end(); ?>
